def transform(grid):
    # The grid consists of repeating 3-column units. Preserve the fixed
    # separator columns and the even rows; smooth the variable cells on the
    # intervening rows using their vertical neighbors.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(1, h - 1, 2):
        for c in range(1, w, 3):
            if c >= w:
                continue
            above = grid[r - 1][c]
            below = grid[r + 1][c]
            if above == below:
                out[r][c] = above
    return out
